(function(){'use strict';const W=DecideWorldTravel,D=EvervaleMapData,el=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));let selectedRoute='',selectedEvent='',playRoute='',playMode='walk';const aside=el('mapEditorScreen').querySelector('aside'),editor=document.createElement('article');editor.id='worldRoutesEditor';editor.innerHTML=`<h2>เส้นทางและระยะทาง</h2><p>เชื่อมสถานที่ด้วยเส้นทาง ID คงที่ ชื่อและตำแหน่งแก้ได้โดยอีเวนต์ยังอ้างอิงถูก</p><label>ID เส้นทางใหม่ (เว้นว่างให้สร้างเอง)<input id="routeNewId" maxlength="80" placeholder="เช่น ROAD-001"></label><button id="routeAdd">เพิ่มเส้นทาง</button><label>เลือกเส้นทาง<select id="routeSelect"></select></label><div id="routeFields"><label>ID อ้างอิง<input id="routeId" readonly></label><label>ชื่อเส้นทาง<input id="routeName" maxlength="100"></label><label>ต้นทาง<select id="routeFrom"></select></label><label>ปลายทาง<select id="routeTo"></select></label><label>ระยะทาง (กม.)<input id="routeKm" type="number" min="0.1" max="100000" step="0.1"></label><label>สภาพทาง<select id="routeTerrain"></select></label><label class="check"><input id="routeOneWay" type="checkbox">เดินทางทิศเดียว</label><label>โอกาสเริ่มต้นสำหรับอีเวนต์เก่าที่ยังไม่ระบุ (%)<input id="routeChance" type="number" min="0" max="100" step="1"></label><label class="check"><input id="routeEnabled" type="checkbox">เปิดใช้เส้นทาง</label><p id="routeEstimate" class="muted"></p><button id="routeDelete">ลบเส้นทาง</button></div><details><summary>ค่าประมาณการเดินทาง</summary><p>เป็นค่าประมาณสำหรับเกม แก้ให้เหมาะกับโลกของคุณได้ พักส่วนที่เหลือของวันหลังเดินทางครบชั่วโมงต่อวัน</p><label>เดินเท้า (กม./ชม.)<input id="travelWalkSpeed" type="number" min="0.1" max="20" step="0.1"></label><label>รถม้า (กม./ชม.)<input id="travelCartSpeed" type="number" min="0.1" max="30" step="0.1"></label><label>เดินทางวันละ (ชม.)<input id="travelHours" type="number" min="1" max="16" step="1"></label><label>ตรวจอีเวนต์ทุกระยะ (กม.)<input id="travelCheckpoint" type="number" min="0.1" max="1000" step="0.1"></label><small>ค่าเริ่มต้น: เท้า 4 / รถม้า 6 กม./ชม. วันละ 8 ชม. พัก 16 ชม. ระหว่างวันเดินทาง รถม้าผ่านป่าหรือภูเขาที่ไม่มีถนนไม่ได้</small></details><hr><h2>อีเวนต์ระหว่างทาง</h2><p>กำหนด % ต่ออีเวนต์ บทพูด NPC ไอเท็ม เควส และบทหลังต่อสู้ได้ที่ หน้าฐานข้อมูล → อีเวนต์ / บทสนทนา</p><label>ID อีเวนต์ใหม่ (ไม่จำเป็น)<input id="routeEventNewId" maxlength="80" placeholder="เช่น EVT-001"></label><button id="routeEventAdd">เพิ่มอีเวนต์</button><label>เลือกอีเวนต์<select id="routeEventSelect"></select></label><div id="routeEventFields"><label>ID อ้างอิง<input id="routeEventId" readonly></label><label>ชื่อเหตุการณ์<input id="routeEventName" maxlength="100"></label><label>ข้อความ<textarea id="routeEventText" rows="3" maxlength="4000"></textarea></label><label>รูปแบบ<select id="routeEventKind"><option value="story">สนทนา / ตัวเลือก</option><option value="combat">เข้าสู้บน grid</option></select></label><label class="check"><input id="routeEventAll" type="checkbox">เกิดได้ทุกเส้นทาง</label><fieldset id="routeEventRoutes"><legend>เกิดใน ID เส้นทางใดบ้าง</legend></fieldset><label>ช่องเดิม (เลิกใช้น้ำหนักแล้ว — กำหนด % แยกในฐานข้อมูลอีเวนต์)<input id="routeEventWeight" type="number" min="1" max="1000" step="1"></label><label class="check"><input id="routeEventOnce" type="checkbox">เกิดครั้งเดียวต่อเซฟ</label><label class="check"><input id="routeEventEnabled" type="checkbox">เปิดใช้อีเวนต์ (ต้องเลือกเส้นทางก่อน)</label><div id="routeEventStory"><h3>ตัวเลือกและผลลัพธ์</h3><div id="routeEventChoices"></div><button id="routeChoiceAdd">เพิ่มตัวเลือก</button></div><div id="routeEventCombat"><label>ฉากต่อสู้<select id="routeEventScene"></select></label><label>มอนสเตอร์<select id="routeEventMonster"></select></label><label>จำนวนศัตรู<input id="routeEventEnemies" type="number" min="1" max="5" step="1"></label><label>เวลาเหตุการณ์เพิ่มเติม (นาที)<input id="routeEventMinutes" type="number" min="0" max="10080" step="1"></label><label class="check"><input id="routeEventRetreat" type="checkbox">ให้หลีกเลี่ยง / ถอนตัวได้</label></div><button id="routeEventDelete">ลบอีเวนต์นี้</button></div><p id="worldRouteEditorStatus" role="status"></p>`;aside.append(editor);
const panel=document.createElement('article');panel.id='worldTravelPanel';panel.innerHTML='<h2>เดินทางระหว่างสถานที่</h2><div id="worldTravelBody"></div><p id="worldTravelStatus" role="status"></p>';el('gameMapCanvas').after(panel);
const fmt=minutes=>{const days=Math.floor(minutes/1440),h=Math.floor(minutes%1440/60),m=minutes%60;return (days?days+' วัน ':'')+(h?h+' ชม. ':'')+(m?m+' นาที':'')||'0 นาที';};
const draft=()=>window.EvervaleMaps?.editConfig(),conf=()=>DB.overrides?.[D.KEY]||D.defaults(),allPoints=c=>c.maps.flatMap(m=>m.locations.map(p=>({value:m.id+'/'+p.id,label:m.name+' · '+p.name+(p.enabled?'':' (ซ่อน)'),point:{mapId:m.id,placeId:p.id}}))),end=value=>{const [mapId,placeId]=value.split('/');return {mapId,placeId};},rid=()=>draft()?.routes?.find(r=>r.id===selectedRoute),ev=()=>draft()?.events?.find(e=>e.id===selectedEvent);
function touch(){EvervaleMaps.touch();el('worldRouteEditorStatus').textContent='มีการแก้ไขเส้นทาง/อีเวนต์ • กดบันทึกแผนที่และซิงก์';}
function run(fn){try{fn();}catch(e){el('worldRouteEditorStatus').textContent=e.message;}}
function ensure(){const c=draft();if(c){c.routes??=[];c.events??=[];c.travelSettings??={...W.defaults};}return c;}
function optionList(select,list,value){select.replaceChildren();for(const item of list)select.add(new Option(item.label,item.value));select.value=list.some(v=>v.value===value)?value:list[0]?.value||'';}
function estimateText(r,c){return ['walk','cart'].map(mode=>{try{const t=W.estimate(r,mode,c.travelSettings);return (mode==='walk'?'เท้า':'รถม้า')+': เคลื่อนที่ '+fmt(t.movingMinutes)+' / '+t.travelDays+' วันเดินทาง / รวมพัก '+fmt(t.elapsedMinutes);}catch(e){return (mode==='cart'?'รถม้า: ':'เท้า: ')+e.message;}}).join(' • ');}
function renderEditor(){const c=ensure();if(!c)return;if(!c.routes.some(r=>r.id===selectedRoute))selectedRoute=c.routes[0]?.id||'';if(!c.events.some(e=>e.id===selectedEvent))selectedEvent=c.events[0]?.id||'';optionList(el('routeSelect'),c.routes.map(r=>({value:r.id,label:r.id+' · '+r.name})),selectedRoute);const r=rid(),points=allPoints(c);el('routeFields').hidden=!r;el('routeAdd').disabled=points.length<2||c.routes.length>=300;if(r){el('routeId').value=r.id;el('routeName').value=r.name;optionList(el('routeFrom'),points,W.key(r.from));optionList(el('routeTo'),points,W.key(r.to));el('routeKm').value=r.km;optionList(el('routeTerrain'),Object.entries(W.terrain).map(([value,t])=>({value,label:t.name})),r.terrain);el('routeOneWay').checked=r.oneWay;el('routeChance').value=r.eventChance;el('routeEnabled').checked=r.enabled;el('routeEstimate').textContent=estimateText(r,c);}for(const [id,key]of [['travelWalkSpeed','walkKmh'],['travelCartSpeed','cartKmh'],['travelHours','hoursPerDay'],['travelCheckpoint','checkpointKm']])el(id).value=c.travelSettings[key];optionList(el('routeEventSelect'),c.events.map(e=>({value:e.id,label:e.id+' · '+e.name})),selectedEvent);const e=ev();el('routeEventWeight').disabled=true;el('routeEventFields').hidden=!e;if(!e)return;for(const [id,key]of [['routeEventId','id'],['routeEventName','name'],['routeEventText','text'],['routeEventKind','kind'],['routeEventWeight','weight']])el(id).value=e[key];el('routeEventAll').checked=e.allRoutes;el('routeEventOnce').checked=e.once;el('routeEventEnabled').checked=e.enabled;const routes=el('routeEventRoutes');routes.replaceChildren();const legend=document.createElement('legend');legend.textContent='เกิดใน ID เส้นทางใดบ้าง';routes.append(legend);for(const r of c.routes){const label=document.createElement('label'),check=document.createElement('input');label.className='check';check.type='checkbox';check.value=r.id;check.checked=e.routeIds.includes(r.id);check.disabled=e.allRoutes;check.onchange=()=>{e.routeIds=[...routes.querySelectorAll('input:checked')].map(x=>x.value);if(e.routeChances)e.routeChances=e.routeIds.map(routeId=>e.routeChances.find(b=>b.routeId===routeId)||{routeId,chance:c.routes.find(r=>r.id===routeId)?.eventChance??20});touch();};label.append(check,document.createTextNode(r.id+' · '+r.name));routes.append(label);}el('routeEventStory').hidden=e.kind!=='story'||!!e.novel;el('routeEventCombat').hidden=e.kind!=='combat';renderChoices(e);if(e.kind==='combat'){const Battle=EverTaleBattleData,source=(DB.overrides?.[Battle.KEY]||Battle.defaults()).scenes,options=[{value:'',label:'สนามถนนจำลอง 12×10'},...source.map(s=>({value:s.id,label:s.name})),...DecideBattlePresets.catalog.map(s=>({value:'preset:'+s.id,label:'พรีเซ็ต '+s.name}))];if(e.sceneId&&!options.some(o=>o.value===e.sceneId))options.push({value:e.sceneId,label:'ไม่พบฉากเดิม: '+e.sceneId});optionList(el('routeEventScene'),options,e.sceneId||'');const monsters=R.records(DB).filter(r=>r.kind==='monster'&&r.enabled!==false);const monsterOptions=[{value:'',label:'ใช้ข้อมูลฉาก / มอนสเตอร์เริ่มต้น'},...monsters.map(r=>({value:r.id,label:r.displayName||r.name}))];if(e.monsterId&&!monsterOptions.some(o=>o.value===e.monsterId))monsterOptions.push({value:e.monsterId,label:'ไม่พบมอนสเตอร์เดิม: '+e.monsterId});optionList(el('routeEventMonster'),monsterOptions,e.monsterId||'');el('routeEventEnemies').value=e.enemyCount??1;el('routeEventMinutes').value=e.minutes??0;el('routeEventRetreat').checked=e.allowRetreat!==false;}}
function renderChoices(e){const root=el('routeEventChoices');root.replaceChildren();if(e.kind!=='story')return;for(const ch of e.choices||[]){const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent='ตัวเลือก '+ch.id;box.append(legend);for(const [key,title,type]of [['label','ข้อความปุ่ม','text'],['text','ผลที่บรรยาย','text'],['goldDelta','เหรียญ (+รับ / -จ่าย)','number'],['energyDelta','พลังงาน (+/-)','number'],['minutes','เวลาเพิ่ม (นาที)','number']]){const label=document.createElement('label'),input=document.createElement('input');label.textContent=title;input.type=type;input.value=ch[key]??'';input.maxLength=key==='text'?2000:150;input.oninput=()=>{ch[key]=type==='number'?Number(input.value):input.value;touch();};label.append(input);box.append(label);}const remove=document.createElement('button');remove.textContent='ลบตัวเลือก';remove.onclick=()=>run(()=>{if(e.choices.length<=1)throw Error('ต้องเหลืออย่างน้อยหนึ่งตัวเลือก');e.choices=e.choices.filter(v=>v.id!==ch.id);touch();renderChoices(e);});box.append(remove);root.append(box);}el('routeChoiceAdd').disabled=e.choices.length>=6;}
function newId(prefix,input,list){const value=input.value.trim()||prefix+'-'+crypto.randomUUID();W.id(value);if(list.some(v=>v.id===value))throw Error('ID ซ้ำ');input.value='';return value;}
el('routeAdd').onclick=()=>run(()=>{const c=ensure(),points=allPoints(c);if(points.length<2)throw Error('เพิ่มสถานที่อย่างน้อย 2 จุดก่อน');const r={id:newId('route',el('routeNewId'),c.routes),name:'เส้นทางใหม่',from:points[0].point,to:points[1].point,km:1,terrain:'road',oneWay:false,eventChance:20,enabled:true};c.routes.push(r);selectedRoute=r.id;touch();renderEditor();EvervaleMaps.refreshStage();});el('routeSelect').onchange=()=>{selectedRoute=el('routeSelect').value;renderEditor();};
for(const [id,key,type]of [['routeName','name','text'],['routeFrom','from','end'],['routeTo','to','end'],['routeKm','km','number'],['routeTerrain','terrain','text'],['routeOneWay','oneWay','check'],['routeChance','eventChance','number'],['routeEnabled','enabled','check']])el(id)[type==='text'&&id==='routeName'||type==='number'?'oninput':'onchange']=()=>{const r=rid();if(!r)return;r[key]=type==='number'?Number(el(id).value):type==='check'?el(id).checked:type==='end'?end(el(id).value):el(id).value;touch();el('routeEstimate').textContent=estimateText(r,draft());EvervaleMaps.refreshStage();};
el('routeDelete').onclick=()=>run(()=>{const c=draft(),r=rid();if(!r||!confirm('ลบเส้นทาง '+r.id+'? อีเวนต์ที่ไม่เหลือเส้นทางจะพักไว้'))return;c.routes=c.routes.filter(v=>v.id!==r.id);W.prune(c);selectedRoute='';touch();renderEditor();EvervaleMaps.refreshStage();});for(const [id,key]of [['travelWalkSpeed','walkKmh'],['travelCartSpeed','cartKmh'],['travelHours','hoursPerDay'],['travelCheckpoint','checkpointKm']])el(id).oninput=()=>{draft().travelSettings[key]=Number(el(id).value);touch();if(rid())el('routeEstimate').textContent=estimateText(rid(),draft());};
el('routeEventAdd').onclick=()=>run(()=>{const c=ensure();if(c.events.length>=200)throw Error('อีเวนต์เต็ม');const e={id:newId('event',el('routeEventNewId'),c.events),name:'เหตุการณ์ใหม่',kind:'story',text:'',routeIds:[],allRoutes:false,weight:1,once:false,enabled:false,choices:[{id:'continue',label:'เดินทางต่อ',text:'',goldDelta:0,energyDelta:0,minutes:0}]};c.events.push(e);selectedEvent=e.id;touch();renderEditor();});el('routeEventSelect').onchange=()=>{selectedEvent=el('routeEventSelect').value;renderEditor();};
for(const [id,key,type]of [['routeEventName','name','text'],['routeEventText','text','text'],['routeEventWeight','weight','number'],['routeEventOnce','once','check'],['routeEventEnabled','enabled','check'],['routeEventScene','sceneId','select'],['routeEventMonster','monsterId','select'],['routeEventEnemies','enemyCount','number'],['routeEventMinutes','minutes','number'],['routeEventRetreat','allowRetreat','check']])el(id)[type==='text'||type==='number'?'oninput':'onchange']=()=>{const e=ev();if(!e)return;e[key]=type==='check'?el(id).checked:type==='number'?Number(el(id).value):el(id).value;touch();};el('routeEventAll').onchange=()=>{ev().allRoutes=el('routeEventAll').checked;touch();renderEditor();};el('routeEventKind').onchange=()=>{const e=ev();e.kind=el('routeEventKind').value;if(e.kind==='combat')Object.assign(e,{sceneId:e.sceneId||'',monsterId:e.monsterId||'',enemyCount:e.enemyCount||1,allowRetreat:e.allowRetreat!==false,minutes:e.minutes||0});else e.choices??=[{id:'continue',label:'เดินทางต่อ',text:'',goldDelta:0,energyDelta:0,minutes:0}];touch();renderEditor();};el('routeChoiceAdd').onclick=()=>run(()=>{const e=ev();if(e.choices.length>=6)return;e.choices.push({id:'choice-'+crypto.randomUUID(),label:'ตัวเลือกใหม่',text:'',goldDelta:0,energyDelta:0,minutes:0});touch();renderChoices(e);});el('routeEventDelete').onclick=()=>run(()=>{const e=ev();if(!e||!confirm('ลบอีเวนต์ '+e.id+'?'))return;draft().events=draft().events.filter(v=>v.id!==e.id);selectedEvent='';touch();renderEditor();});
const ns='http://www.w3.org/2000/svg';function drawRoutes(stage,c,m){stage.querySelector('.world-route-layer')?.remove();if(!(c.routes||[]).length)return;const svg=document.createElementNS(ns,'svg');svg.classList.add('world-route-layer');svg.setAttribute('viewBox','0 0 '+m.width+' '+m.height);svg.setAttribute('preserveAspectRatio','none');for(const r of c.routes.filter(r=>r.from.mapId===m.id&&r.to.mapId===m.id)){const a=W.point(c,r.from),b=W.point(c,r.to);if(!a||!b)continue;const line=document.createElementNS(ns,'line');line.dataset.routeId=r.id;line.setAttribute('x1',a.x*m.width/100);line.setAttribute('y1',a.y*m.height/100);line.setAttribute('x2',b.x*m.width/100);line.setAttribute('y2',b.y*m.height/100);line.setAttribute('stroke',r.enabled===false?'#87958b':'#ebc783');line.setAttribute('stroke-width','3');line.setAttribute('vector-effect','non-scaling-stroke');if(r.enabled===false)line.setAttribute('stroke-dasharray','6 5');const title=document.createElementNS(ns,'title');title.textContent=r.id+' · '+r.name+' · '+r.km+' กม.'+(r.oneWay?' (ทิศเดียว)':'');line.append(title);const label=document.createElementNS(ns,'text');label.setAttribute('x',(a.x+b.x)/2*m.width/100);label.setAttribute('y',(a.y+b.y)/2*m.height/100);label.setAttribute('font-size',String(Math.max(12,m.width/50)));label.setAttribute('text-anchor','middle');label.textContent=(r.oneWay?'→ ':'')+r.km+' กม.';label.onclick=e=>{e.stopPropagation();if(stage.id==='mapEditorCanvas'){selectedRoute=r.id;renderEditor();el('routeId').scrollIntoView({block:'nearest'});}else{playRoute=r.id;renderGame();}};svg.append(line,label);}stage.append(svg);}
function geometry(stage,c,m){drawRoutes(stage,c,m);}
function button(root,id,label,fn,disabled=false){const b=document.createElement('button');b.id=id;b.textContent=label;b.disabled=disabled;b.onclick=()=>play(fn);root.append(b);return b;}
function para(root,text,tag='p'){const p=document.createElement(tag);p.textContent=text;root.append(p);return p;}
function play(fn){try{s=fn();save();render();if(s.expedition)EverTaleCombat.launch();}catch(e){el('worldTravelStatus').textContent=e.message;}}
function renderGame(){if(!s.character)return;const c=conf(),root=el('worldTravelBody');root.replaceChildren();panel.hidden=!(c.routes||[]).length&&!s.overworld?.journey;if(panel.hidden)return;el('worldTravelStatus').textContent='';DecideEventNovelUI.journal(root,s);const w=W.current(s,c),j=w.journey,p=W.point(c,w.location);para(root,'ตำแหน่งจริง: '+(p?.name||'สถานที่เดิมถูกลบ/ปิด')+(j?' • ระหว่างเดินทาง':''));if(j){const total=W.estimate(j.route,j.mode,j.settings);para(root,j.fromName+' → '+j.toName+' • '+j.route.id+' • '+j.progressKm+'/'+j.route.km+' กม.');para(root,'ผ่านไป '+fmt(j.elapsedMinutes+j.eventMinutes)+' • เดินทางคงเหลือตามแผน '+fmt(total.elapsedMinutes-j.elapsedMinutes));if(s.expedition){button(root,'worldResumeBattle','กลับเข้าสู่การต่อสู้',()=>s);return;}const pending=j.pendingEvent;if(pending){const e=W.activeEvent(pending);para(root,e.name,'h3');para(root,'เหตุการณ์ที่รอต่ออีก '+(j.eventQueue?.length||0)+' เหตุการณ์');if(e.kind==='story'&&e.novel)DecideEventNovelUI.render(root,s,pending,R.records(DB),id=>play(()=>W.resolve(s,id,R.records(DB))));else if(e.kind==='story'){para(root,e.text);for(const choice of e.choices)button(root,'worldChoice-'+choice.id,choice.label+(choice.goldDelta?' ('+(choice.goldDelta>0?'+':'')+choice.goldDelta+' เหรียญ)':''),()=>W.resolve(s,choice.id,R.records(DB)),s.gold+choice.goldDelta<0);}else{button(root,'worldFight','เข้าสู่การต่อสู้',()=>DecideWorldTravelCombat.begin(s,R.records(DB),DB.overrides));if(e.allowRetreat)button(root,'worldSkip','หลีกเลี่ยงเหตุการณ์',()=>W.skip(s));}}else button(root,'worldAdvance','เดินทางต่ออีกไม่เกิน '+j.settings.checkpointKm+' กม.',()=>W.advance(s));button(root,'worldCamp','พักแรมฟื้นพลัง · 8 ชั่วโมง',()=>DecideWorldTravelCombat.camp(s,R.records(DB)));return;}
if(!s.overworld||!p?.enabled){const label=document.createElement('label'),select=document.createElement('select');label.textContent=!s.overworld?'ยืนยันจุดเริ่ม (ตั้งได้ครั้งแรก)':'ซ่อมตำแหน่งเดิมที่ถูกลบ/ปิด';select.id='worldStartPoint';optionList(select,allPoints(c).filter(v=>W.point(c,v.point)?.enabled),w.location?W.key(w.location):'');label.append(select);root.append(label);button(root,'worldSetStart','ยืนยันตำแหน่ง',()=>W.setStart(s,c,end(select.value)));}
const routes=W.available(s,c);if(!routes.length){para(root,'ไม่มีเส้นทางเปิดจากตำแหน่งนี้ เพิ่มเส้นทางเชื่อมในหน้าแก้ไขแผนที่');return;}if(!routes.some(r=>r.id===playRoute))playRoute=routes[0].id;const select=document.createElement('select');select.id='worldRouteChoice';optionList(select,routes.map(r=>({value:r.id,label:r.id+' · '+r.name+' · '+r.km+' กม.'})),playRoute);select.onchange=()=>{playRoute=select.value;renderGame();};root.append(select);const mode=document.createElement('select');mode.id='worldTravelMode';optionList(mode,[{value:'walk',label:'เดินเท้า'},{value:'cart',label:'รถม้า'}],playMode);mode.onchange=()=>{playMode=mode.value;renderGame();};root.append(mode);const r=routes.find(r=>r.id===playRoute);let valid=true;try{const est=W.estimate(r,playMode,c.travelSettings);para(root,'ความเร็วประมาณ '+Number(est.speedKmh.toFixed(2))+' กม./ชม. • เคลื่อนที่ '+fmt(est.movingMinutes)+' • '+est.travelDays+' วันเดินทาง • รวมพัก '+fmt(est.elapsedMinutes));}catch(e){valid=false;para(root,e.message);}button(root,'worldBegin','เริ่มเดินทาง',()=>W.begin(s,c,r.id,playMode),!valid||!!s.event||s.dead);para(root,'กดดูสถานที่บนภาพได้โดยไม่เสียเวลา การเดินทางจริงใช้เส้นทางที่เลือก • เวลาอีเวนต์/พักเพิ่มแยกจากค่าประมาณ');}
function canUse(mapId,placeId){const c=conf();if(s.overworld?.journey)return false;if(!(c.routes||[]).some(r=>r.enabled!==false&&(r.from.mapId===mapId||r.to.mapId===mapId)))return true;return W.same(W.current(s,c).location,{mapId,placeId});}
window.DecideWorldTravelUI={renderEditor,renderGame,drawRoutes,geometry,canUse,fmt};
})();
